flowchart TD
    A["选择模型<br/>试用提示词，保存原始回答"] --> B["准备数据<br/>检查、清洗并固定划分"]
    B --> C["执行训练<br/>让模型学习训练样本"]
    C --> D["用验证集检查效果"]
    D --> E{"是否选定方案？"}
    E -- "继续调整" --> F["分析错误<br/>调整训练数据或设置"]
    F --> C
    E -- "是" --> G["使用独立测试集<br/>比较微调前后的回答"]
    G --> H["根据结果决定是否使用<br/>满足要求后再导出、部署"]

    classDef prep fill:#eff6ff,stroke:#2563eb,color:#1e3a8a;
    classDef decision fill:#fff7ed,stroke:#f97316,color:#9a3412;
    classDef result fill:#ecfdf5,stroke:#0f766e,color:#115e59;
    class A,B,C,D,F,G prep;
    class E decision;
    class H result;

